#include <string>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxFreq(std::string s, int maxLetters, int minSize, int maxSize) {
        std::unordered_map<std::string, int> counts;
        int n = s.size();
        int maxCount = 0;
        for (int i = 0; i <= n - minSize; ++i) {
            std::string sub = s.substr(i, minSize);
            std::unordered_set<char> chars(sub.begin(), sub.end());
            if (chars.size() <= (size_t)maxLetters) {
                counts[sub]++;
                maxCount = std::max(maxCount, counts[sub]);
            }
        }
        return maxCount;
    }
};

import java.util.*;

class Solution {
    public int maxFreq(String s, int maxLetters, int minSize, int maxSize) {
        Map<String, Integer> counts = new HashMap<>();
        int n = s.length();
        int maxCount = 0;
        for (int i = 0; i <= n - minSize; i++) {
            String sub = s.substring(i, i + minSize);
            Set<Character> chars = new HashSet<>();
            for (char ch : sub.toCharArray()) chars.add(ch);
            if (chars.size() <= maxLetters) {
                int c = counts.getOrDefault(sub, 0) + 1;
                counts.put(sub, c);
                maxCount = Math.max(maxCount, c);
            }
        }
        return maxCount;
    }
}

var maxFreq = function(s, maxLetters, minSize, maxSize) {
    const counts = new Map();
    const n = s.length;
    let maxCount = 0;
    for (let i = 0; i <= n - minSize; i++) {
        const sub = s.substring(i, i + minSize);
        const chars = new Set(sub);
        if (chars.size() <= maxLetters) {
            const c = (counts.get(sub) || 0) + 1;
            counts.set(sub, c);
            if (c > maxCount) maxCount = c;
        }
    }
    return maxCount;
};
